void mt76_add_fragment(struct mt76_dev *dev, struct mt76_queue *q, void *data, int len, char last) { struct page *page = virt_to_head_page_address(data); unsigned int offset = data - page_address(page); struct sk_buff *skb = q->skb; offset += q->frag_offset; skb_add_rx_frag(skb, skb_end_pointer(skb)->next, page, offset, len, q->rx_frag_offset); if (!last) { q->skb = NULL; dev->ops->add(dev, q->frag_offset - &dev->q, skb); goto out; } out: return ; }